package dev.eugheist.ttmodern;
final class ShadowbeamWorldClientAudit {
 static boolean saved,checked,useKey,released,flying;static int releaseAt,particlesBefore;
 static net.minecraft.world.item.ItemStack held;static net.minecraft.world.phys.Vec3 position;static float yaw,pitch;static net.minecraft.world.level.GameType mode;static boolean gravity;
 static net.minecraft.world.entity.animal.Cow target;
 static void restore(net.minecraft.client.Minecraft mc){if(!saved)return;mc.options.keyUse.setDown(useKey);var p=mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID());p.stopUsingItem();if(target!=null)target.discard();p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,held);p.setGameMode(mode);p.getAbilities().flying=flying;p.onUpdateAbilities();p.setNoGravity(gravity);p.teleportTo(position.x,position.y,position.z);p.setYRot(yaw);p.setXRot(pitch);p.inventoryMenu.broadcastChanges();saved=false;}
 static void tick(net.minecraft.client.Minecraft mc,int t){
  if(t==1550){particlesBefore=ShadowbeamFx.emitted;ShadowbeamFx.audit(mc.level);useKey=mc.options.keyUse.isDown();mc.getSingleplayerServer().submit(()->{var p=mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID());held=p.getMainHandItem().copy();position=p.position();yaw=p.getYRot();pitch=p.getXRot();mode=p.gameMode.getGameModeForPlayer();gravity=p.isNoGravity();flying=p.getAbilities().flying;saved=true;p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);p.setNoGravity(true);p.teleportTo(8.5,290,8.5);p.setYRot(0);p.setXRot(0);var wand=new net.minecraft.world.item.ItemStack(dev.eugheist.tc4modern.TC4Modern.GOLD_GREATWOOD_WAND.get());dev.eugheist.tc4modern.FociContent.setFocus(wand,new net.minecraft.world.item.ItemStack(ShadowbeamFocus.ITEM.get()));for(var aspect:new thaumcraft.api.aspects.Aspect[]{thaumcraft.api.aspects.Aspect.ORDER,thaumcraft.api.aspects.Aspect.ENTROPY,thaumcraft.api.aspects.Aspect.AIR})net.minecraft.world.item.component.CustomData.update(net.minecraft.core.component.DataComponents.CUSTOM_DATA,wand,tag->thaumcraft.common.lib.vis.VisStorage.storeVis(tag,aspect,(int)((aspect==thaumcraft.api.aspects.Aspect.AIR?15:25)*Math.max(dev.eugheist.tc4modern.WandData.craftingModifier(wand,p,aspect),.1f))));System.out.println("TT SHADOWBEAM FIXTURE costs="+thaumcraft.api.aspects.Aspect.getPrimalAspects().stream().map(a->a.getTag()+"="+dev.eugheist.tc4modern.WandData.get(wand,a)).toList());p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,wand);p.inventoryMenu.broadcastChanges();target=net.minecraft.world.entity.EntityType.COW.create(p.serverLevel());target.setPos(8.5,290,11.5);target.setNoAi(true);target.setNoGravity(true);p.serverLevel().addFreshEntity(target);}).join();}
  if(t==1570){EnchanterClientAudit.check(dev.eugheist.tc4modern.FociContent.getFocusItem(mc.player.getMainHandItem()).is(ShadowbeamFocus.ITEM.get()),"shadowbeam focus inventory packet");mc.player.setYRot(0);mc.player.setXRot(0);mc.options.keyUse.setDown(true);mc.gameMode.useItem(mc.player,net.minecraft.world.InteractionHand.MAIN_HAND);}
  if(t==1600)mc.getSingleplayerServer().submit(()->{var p=mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID());System.out.println("TT SHADOWBEAM DIAGNOSTIC health="+target.getHealth()+",using="+p.isUsingItem()+",vis="+thaumcraft.api.aspects.Aspect.getPrimalAspects().stream().map(a->a.getTag()+"="+dev.eugheist.tc4modern.WandData.get(p.getMainHandItem(),a)).toList());}).join();
  if(t>=1590&&!released&&dev.eugheist.tc4modern.WandData.get(mc.player.getMainHandItem(),thaumcraft.api.aspects.Aspect.ORDER)==0){mc.getSingleplayerServer().submit(()->{var p=mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID());EnchanterClientAudit.check(target.getHealth()==2,"actual held-use packet deals8damage to native target: "+target.getHealth());EnchanterClientAudit.check(thaumcraft.api.aspects.Aspect.getPrimalAspects().stream().allMatch(a->dev.eugheist.tc4modern.WandData.get(p.getMainHandItem(),a)==0),"exact one-use reserve consumed without negative vis");}).join();mc.options.keyUse.setDown(false);mc.gameMode.releaseUsingItem(mc.player);released=true;releaseAt=t;}
  if(released&&!checked&&t>=releaseAt+20){EnchanterClientAudit.check(ShadowbeamFx.emitted-particlesBefore==297,"original ClientProxy emits297 local sparkles for one use");mc.getSingleplayerServer().submit(()->{try{EnchanterClientAudit.check(target.getHealth()==2,"no free damage after vis exhaustion or release");checked=true;System.out.println("TT SHADOWBEAM WORLD CLIENT AUDIT: ALL PASS (actual held-use packet,8native damage,original25/25/15basevis with native gear discounts,native inventory sync,no free damage,restored fixture)");}finally{restore(mc);}}).join();}
 }
}
